<script setup>
import { computed } from 'vue'
import Campo from '@/components/ui/Campo.vue'
import LinkField from './LinkField.vue'
import AttachField from './AttachField.vue'
import ChildTableField from './ChildTableField.vue'

const props = defineProps({
  field: { type: Object, required: true }, // {fieldname, fieldtype, label, options, reqd}
  readOnly: { type: Boolean, default: false },
  doctype: { type: String, default: '' }, // contexto para adjuntar archivos
  docname: { type: String, default: '' },
  // Oculta la etiqueta del control: lo usan las celdas de una tabla hija, donde
  // el rótulo ya lo da la cabecera de la columna (evita repetirlo fila por fila).
  hideLabel: { type: Boolean, default: false },
})

const value = defineModel({ default: null })

const TEXTAREA_TYPES = new Set(['Text', 'Small Text', 'Long Text', 'Text Editor', 'Code', 'Markdown Editor', 'HTML Editor', 'JSON'])
const NUMBER_TYPES = new Set(['Int', 'Float', 'Currency', 'Percent'])

const label = computed(() => props.field.label || props.field.fieldname)

// El sistema SABE qué campos son obligatorios (`reqd` en el meta) y el
// formulario no lo decía: te enterabas al pulsar «Crear» y recibir un rechazo.
// `Campo` ya pinta el asterisco desde siempre; nadie le pasaba el dato.
//
// Un campo de solo lectura nunca se marca obligatorio aunque lo sea: pedirle a
// alguien que rellene algo que no puede tocar es peor que no avisar. Los que
// sella el sistema (`aprobado_por`, la firma de quien aprueba) caen aquí.
const esObligatorio = computed(() => Boolean(props.field.reqd) && !props.readOnly)

const selectOptions = computed(() => {
  const raw = (props.field.options || '').split('\n').map((s) => s.trim())
  return raw.map((v) => ({ label: v || '—', value: v }))
})

// "Small Text" se ve como una sola línea en el prototipo del Desk, pero en la
// práctica siempre son párrafos cortos (alcance, justificación) — un textarea
// de pocas filas es más honesto que un <input> de una línea que los trunca.
function rowsFor(fieldtype) {
  return fieldtype === 'Small Text' ? 2 : 4
}
</script>

<template>
  <div class="space-y-1.5">
  <div v-if="field.fieldtype === 'Link'" class="space-y-1.5">
    <label v-if="!hideLabel" class="sb-field-label block">
      {{ label }}<span v-if="esObligatorio" class="text-peligro" aria-hidden="true"> *</span>
    </label>
    <LinkField
      v-model="value"
      :doctype="field.options"
      :placeholder="`Buscar ${label}…`"
      :disabled="readOnly"
    />
  </div>

  <AttachField
    v-else-if="field.fieldtype === 'Attach' || field.fieldtype === 'Attach Image'"
    v-model="value"
    :field="field"
    :doctype="doctype"
    :docname="docname"
    :read-only="readOnly"
  />

  <div v-else-if="field.fieldtype === 'Dynamic Link'" class="space-y-1.5">
    <Campo v-model="value" type="text" :label="hideLabel ? undefined : label" :disabled="readOnly" :required="esObligatorio" />
    <p v-if="!hideLabel" class="text-xs text-tinta-tenue">
      Enlace dinámico — el tipo de documento lo define otro campo. Si no es evidente, editar desde el Desk.
    </p>
  </div>

  <Campo
    v-else-if="field.fieldtype === 'Select'"
    type="select"
    v-model="value"
    :label="hideLabel ? undefined : label"
    :options="selectOptions"
    :disabled="readOnly" :required="esObligatorio"
  />

  <Campo
    v-else-if="field.fieldtype === 'Check'"
    type="checkbox"
    :label="hideLabel ? undefined : label"
    :model-value="Boolean(Number(value))"
    :disabled="readOnly"
    @update:model-value="value = $event ? 1 : 0" :required="esObligatorio"
  />

  <Campo
    v-else-if="field.fieldtype === 'Date'"
    type="date"
    v-model="value"
    :label="hideLabel ? undefined : label"
    :disabled="readOnly" :required="esObligatorio"
  />

  <Campo
    v-else-if="field.fieldtype === 'Datetime'"
    type="datetime"
    v-model="value"
    :label="hideLabel ? undefined : label"
    :disabled="readOnly" :required="esObligatorio"
  />

  <Campo
    v-else-if="NUMBER_TYPES.has(field.fieldtype)"
    type="number"
    v-model="value"
    :label="hideLabel ? undefined : label"
    :disabled="readOnly" :required="esObligatorio"
  />

  <ChildTableField
    v-else-if="field.fieldtype === 'Table'"
    v-model="value"
    :field="field"
    :read-only="readOnly"
    :doctype="doctype"
    :docname="docname"
  />

  <Campo
    v-else-if="TEXTAREA_TYPES.has(field.fieldtype)"
    type="textarea"
    v-model="value"
    :label="hideLabel ? undefined : label"
    :rows="rowsFor(field.fieldtype)"
    :disabled="readOnly" :required="esObligatorio"
  />

  <Campo v-else type="text" v-model="value" :label="hideLabel ? undefined : label" :disabled="readOnly" :required="esObligatorio" />

    <!-- La ayuda que el propio DocType declara (`description` en el meta). El
         canon pide «ayuda antes del error», y aquí ya estaba escrita: siete
         campos de Documento Controlado la tienen y no se pintaba ninguna. -->
    <p v-if="field.description && !hideLabel" class="text-xs text-tinta-tenue">
      {{ field.description }}
    </p>
  </div>
</template>
